    privacy:
      "మీరు నమోదు చేసేది ఈ బ్రౌజర్‌లోనే ఉంటుంది, ఎక్కడికీ పంపబడదు. స్విచ్‌ను, స్విచ్ తేదీన, మీరు వదిలిన ఫండ్‌లో అమ్మకంగా, చేరిన ఫండ్‌లో కొనుగోలుగా నమోదు చేయండి.",
    loading: "కాలిక్యులేటర్ లోడ్ అవుతోంది...",
    disclaimerLead: "ఇది అంచనా మాత్రమే, పన్ను సలహా కాదు.",
