        body: "ట్రెయిలింగ్ 5 సంవత్సరాల రాబడి సరిగ్గా ఒకే విండోను కొలుస్తుంది: ఈ రోజు నుండి ఐదు సంవత్సరాల వెనక్కి. ప్రారంభ తేదీని కొన్ని నెలలు జరిపితే సమాధానం చాలా మారవచ్చు, ఎందుకంటే అది మీరు మార్కెట్ కనిష్ఠంలో మొదలుపెట్టారా గరిష్ఠంలోనా అనే దానిపై ఆధారపడుతుంది. రోలింగ్ రాబడి ఫండ్ చరిత్రలో సాధ్యమయ్యే ప్రతి 5 సంవత్సరాల విండోను లెక్కించి వ్యాప్తిని చూపిస్తుంది - సాధారణం, అధ్వానం, ఉత్తమం, ఎంత తరచుగా విండో లాభంతో ముగిసింది. అధ్వాన విండో సాధారణంగా పేజీలో అత్యంత సమాచారం ఇచ్చే సంఖ్య: దురదృష్టవంతుడైన పెట్టుబడిదారుడికి నిజంగా వచ్చింది అదే. ఒక్క ట్రెయిలింగ్ సంఖ్య ఇవన్నీ దాచేస్తుంది.",
