        "రిస్కోమీటర్, ఎగ్జిట్ లోడ్, లాక్-ఇన్, కనీస మొత్తాలు, SID బెంచ్‌మార్క్, ఫండ్ మేనేజర్. ఇవి బయటి మూలాల వాస్తవాలు, NAV నుండి లెక్కించినవి కావు - ఈ సైట్‌లో ఎక్కడా రాబడి, రిస్క్ సంఖ్య లేదా ర్యాంకింగ్‌లో ఎప్పుడూ వాడం.",
